pub assume_specification<T, A: Allocator>[ Vec::<T, A>::shrink_to_fit ](
    vec: &mut Vec<T, A>,
)
    ensures
        final(vec)@ == old(vec)@,
;

pub assume_specification<K, V, S, A: Allocator>[
    HashMap::<K, V, S, A>::capacity
](map: &HashMap<K, V, S, A>) -> (capacity: usize)
    ensures
        capacity >= map.len(),
;
